SET LOCAL search_path = "metadata", pg_catalog;
ALTER TABLE "metadata"."v2_documents" ADD COLUMN search_document jsonb NOT NULL DEFAULT '{}';CREATE TABLE "metadata"."asset_details_v2"(asset_id text PRIMARY KEY REFERENCES "metadata"."assets"(id),mime text NOT NULL,width integer NOT NULL CHECK(width BETWEEN 1 AND 8192),height integer NOT NULL CHECK(height BETWEEN 1 AND 8192),variants jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),rejected_until timestamptz,investigation_hold boolean NOT NULL DEFAULT false);
REVOKE ALL ON "metadata"."asset_details_v2" FROM PUBLIC;
CREATE TABLE "metadata"."account_assets_v2"(id uuid PRIMARY KEY,owner_wallet text NOT NULL CHECK(owner_wallet ~ '^0x[a-f0-9]{40}$'),hash text NOT NULL CHECK(hash ~ '^[a-f0-9]{64}$'),size bigint NOT NULL CHECK(size BETWEEN 1 AND 6291456),mime text NOT NULL CHECK(mime IN('image/png','image/jpeg','image/webp')),width integer NOT NULL CHECK(width BETWEEN 1 AND 8192),height integer NOT NULL CHECK(height BETWEEN 1 AND 8192),state text NOT NULL CHECK(state IN('UPLOADING','QUARANTINED','VALIDATING','APPROVED','REJECTED','DELETED')),variants jsonb NOT NULL DEFAULT '{}',scanner_engine text NOT NULL DEFAULT '',scanner_revision text NOT NULL DEFAULT '',moderation_revision bigint NOT NULL DEFAULT 0,blocked boolean NOT NULL DEFAULT false,rejected_until timestamptz,investigation_hold boolean NOT NULL DEFAULT false,deletion_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp());CREATE INDEX ON "metadata"."account_assets_v2"(state,created_at);
REVOKE ALL ON metadata.account_assets_v2 FROM PUBLIC;
CREATE VIEW metadata.assets_v2 AS SELECT "id","pool","hash","state","object_key","scanner_engine","scanner_revision" FROM metadata.assets;
REVOKE ALL ON metadata.assets_v2 FROM PUBLIC;
CREATE VIEW metadata.pools_v2 AS SELECT "pool" FROM metadata.pools;
REVOKE ALL ON metadata.pools_v2 FROM PUBLIC;
CREATE VIEW metadata.documents_v2 AS SELECT "pool","blocked","moderation_revision" FROM metadata.documents;
REVOKE ALL ON metadata.documents_v2 FROM PUBLIC;
CREATE VIEW metadata.asset_details_v2_v2 AS SELECT "asset_id","variants","created_at","investigation_hold" FROM metadata.asset_details_v2;
REVOKE ALL ON metadata.asset_details_v2_v2 FROM PUBLIC;
CREATE VIEW metadata.account_assets_authority_v2 AS SELECT id,owner_wallet,state,blocked FROM metadata.account_assets_v2;
REVOKE ALL ON metadata.account_assets_authority_v2 FROM PUBLIC;
CREATE TABLE "metadata"."metadata_publication_intents_v3"(operation uuid PRIMARY KEY,draft_id uuid NOT NULL,token text NOT NULL,pool text NOT NULL REFERENCES "metadata"."pools"(pool),creator text NOT NULL,creation_tx_hash text NOT NULL,content_hash text NOT NULL CHECK(content_hash ~ '^[a-f0-9]{64}$'),body_hash text NOT NULL CHECK(body_hash ~ '^[a-f0-9]{64}$'),body bytea NOT NULL CHECK(octet_length(body)<=36864),metadata bytea NOT NULL CHECK(octet_length(metadata)<=32768),upload_refs jsonb NOT NULL,envelope bytea NOT NULL,envelope_digest text NOT NULL,nonce text NOT NULL,request_id uuid NOT NULL,account_id uuid NOT NULL,session_id uuid NOT NULL,auth_epoch bigint NOT NULL,admission_response bytea NOT NULL,accepted_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,CHECK(expires_at=accepted_at+interval '30 minutes'),UNIQUE(draft_id,token,content_hash));CREATE TABLE "metadata"."metadata_publication_jobs_v3"(operation uuid PRIMARY KEY REFERENCES "metadata"."metadata_publication_intents_v3"(operation),state text NOT NULL CHECK(state IN('metadata_pending','publishing','published','rejected','authorization_required')),attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count BETWEEN 0 AND 5),fence bigint NOT NULL DEFAULT 0 CHECK(fence>=0),lease_owner uuid,lease_until timestamptz,grant_nonce text NOT NULL,next_at timestamptz NOT NULL,last_error_code text NOT NULL DEFAULT '',result bytea,revision text,updated_at timestamptz NOT NULL);CREATE INDEX metadata_publication_due_v3 ON "metadata"."metadata_publication_jobs_v3"(next_at) WHERE state IN('metadata_pending','publishing');CREATE TABLE "metadata"."metadata_publication_grants_v3"(operation uuid NOT NULL REFERENCES "metadata"."metadata_publication_intents_v3"(operation),nonce text NOT NULL,envelope bytea NOT NULL,envelope_digest text NOT NULL,body_hash text NOT NULL,request_id uuid NOT NULL,account_id uuid NOT NULL,session_id uuid NOT NULL,auth_epoch bigint NOT NULL,response bytea NOT NULL,PRIMARY KEY(operation,nonce));
REVOKE ALL ON metadata.metadata_publication_intents_v3,metadata.metadata_publication_jobs_v3,metadata.metadata_publication_grants_v3 FROM PUBLIC;
CREATE VIEW metadata.auth_committed_blocks AS SELECT chain_id,height,block_hash,integrity FROM indexer.indexer_committed_heads_v2;
REVOKE ALL ON metadata.auth_committed_blocks FROM PUBLIC;
GRANT SELECT(chain_id,height,block_hash,integrity) ON metadata.auth_committed_blocks TO metadata_runtime;
